import { colors } from '@/theme'
import { defineStyles } from '@/utils'
import { StatusBar } from 'expo-status-bar'
import {
	View,
	ScrollView,
	useWindowDimensions,
	NativeSyntheticEvent,
	NativeScrollEvent
} from 'react-native'
import { SkipButton } from './components/SkipButton'
import { SafeAreaView } from 'react-native-safe-area-context'
import { ContinueButton } from './components/ContinueButton'
import { PaginationDots } from './components/PaginationDots'
import { BuildWithoutCoding } from './steps/BuildWithoutCoding'
import { ConnectedToEverything } from './steps/ConnectedToEverything'
import { IdeasToApps } from './steps/IdeasToApps'
import { PublishInOneTap } from './steps/PublishInOneTap'
import { useState, useRef } from 'react'
import { redirectAfterAuth } from '@/utils/redirect-after-auth'
import { prePromptStoreRating } from '@/utils/pre-prompt-store-rating'
import { useBoolVariation } from '@launchdarkly/react-native-client-sdk'

type OnboardingScreen = {
	stepIndex: number
	contentComponent: React.ReactNode
}

const ONBOARDING_SCREENS: OnboardingScreen[] = [
	{
		stepIndex: 0,
		contentComponent: <BuildWithoutCoding />
	},
	{
		stepIndex: 1,
		contentComponent: <ConnectedToEverything />
	},
	{
		stepIndex: 2,
		contentComponent: <PublishInOneTap />
	},
	{
		stepIndex: 3,
		contentComponent: <IdeasToApps />
	}
] as const

export const OnboardingScreen = () => {
	const [stepIndex, setStepIndex] = useState(0)
	const scrollViewRef = useRef<ScrollView>(null)
	const { width: screenWidth } = useWindowDimensions()
	const promptRatingOnboardingEnabled = useBoolVariation(
		'prompt-rating-onboarding-enabled',
		false
	)

	const handleScroll = (event: NativeSyntheticEvent<NativeScrollEvent>) => {
		const offsetX = event.nativeEvent.contentOffset.x
		const currentIndex = Math.round(offsetX / screenWidth)
		setStepIndex(currentIndex)
	}

	const handleContinue = async () => {
		if (stepIndex < ONBOARDING_SCREENS.length - 1) {
			const nextIndex = stepIndex + 1
			scrollViewRef.current?.scrollTo({
				x: nextIndex * screenWidth,
				animated: true
			})
		} else {
			if (promptRatingOnboardingEnabled) {
				await prePromptStoreRating(true)
			}
			await redirectAfterAuth()
		}
	}

	return (
		<>
			<StatusBar style="light" />
			<SafeAreaView style={styles.container} edges={['top', 'bottom']}>
				<View style={styles.skipButtonContainer}>
					<SkipButton show={stepIndex < ONBOARDING_SCREENS.length - 1} />
				</View>

				<ScrollView
					ref={scrollViewRef}
					horizontal
					pagingEnabled
					showsHorizontalScrollIndicator={false}
					onScroll={handleScroll}
					style={styles.scrollView}
					contentContainerStyle={styles.scrollViewContent}
				>
					{ONBOARDING_SCREENS.map((screen) => (
						<View
							key={screen.stepIndex}
							style={[styles.slide, { width: screenWidth }]}
						>
							{screen.contentComponent}
						</View>
					))}
				</ScrollView>

				<View style={styles.footer}>
					<View style={styles.paginationDotsContainer}>
						<PaginationDots
							currentIndex={stepIndex}
							totalPages={ONBOARDING_SCREENS.length}
						/>
					</View>

					<ContinueButton onPress={handleContinue} />
				</View>
			</SafeAreaView>
		</>
	)
}

const styles = defineStyles({
	container: {
		flex: 1,
		backgroundColor: colors.light.gray[900],
		paddingBottom: 28,
		justifyContent: 'flex-end'
	},
	skipButtonContainer: {
		position: 'absolute',
		top: 80,
		right: 20,
		zIndex: 999
	},
	scrollView: {
		flex: 1
	},
	scrollViewContent: {
		alignItems: 'center'
	},
	slide: {
		flex: 1,
		justifyContent: 'center'
	},
	paginationDotsContainer: {
		flexDirection: 'row',
		justifyContent: 'flex-start',
		alignItems: 'center',
		gap: 8
	},
	footer: {
		justifyContent: 'space-between',
		gap: 54,
		paddingHorizontal: 20
	}
})
